     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	
     4	const ZIMM_PRODUCT_NAME_RECIPE = 'ZimmProductName';
     5	
     6	type ZimmProductNameProps = {
     7	  /** The product's display name, already resolved by the caller. */
     8	  name: string;
     9	  /**
    10	   * Heading level. Required rather than defaulted: the correct level depends on what else the
    11	   * page has already emitted, and a silent `h1` default duplicates the base PDP's own
    12	   * screen-reader-only `<h1>Product Details</h1>`.
    13	   */
    14	  as: 'h1' | 'h2' | 'h3';
    15	};
    16	
    17	/**
    18	 * Atom — the product name. Styling lives in `zimmProductName.css.ts` and is consumed through
    19	 * the theme, per the one-canonical-styling-surface rule; only the composite `textStyle` stays
    20	 * on the element, since no single CSS custom property expresses it.
    21	 *
    22	 * The element is written as `chakra.p` with an `as` override rather than a fixed heading tag,
    23	 * which is what Chakra's own `Text` did before the recipe landed: the tag is a caller decision
    24	 * and `as` is the only prop that can carry it. `index.stories.tsx` asserts the heading role and
    25	 * level for all three values so this cannot silently degrade to a `<p>`.
    26	 */
    27	export const ZimmProductName = ({ name, as }: ZimmProductNameProps) => {
    28	  const styles = useStyleConfig(ZIMM_PRODUCT_NAME_RECIPE, {});
    29	
    30	  return (
    31	    <chakra.p as={as} __css={styles} textStyle="heading3" data-testid="product-name">
    32	      {name}
    33	    </chakra.p>
    34	  );
    35	};
=============== overrides/app/components/ui-kits/atoms/zimmProductModelInfo/index.tsx
     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	import { isBlankRichText, parseRichText } from 'app/utils/richText';
     4	
     5	const ZIMM_PRODUCT_MODEL_INFO_RECIPE = 'ZimmProductModelInfo';
     6	
     7	type ZimmProductModelInfoProps = {
     8	  /**
     9	   * Model copy from the product's `c_modelFit` attribute. Business Manager authors this as
    10	   * rich text, so it is parsed rather than rendered as a raw string.
    11	   */
    12	  modelInfo?: string;
    13	};
    14	
    15	/**
    16	 * Atom — the model line ("Model is 178cm and wears a size 0"). Renders nothing when
    17	 * `c_modelFit` is absent, which is the common case today.
    18	 *
    19	 * Styling lives in `zimmProductModelInfo.css.ts` and is consumed through the theme, per the
    20	 * one-canonical-styling-surface rule; only the composite `textStyle` stays on the element.
    21	 *
    22	 * A `div`, not a `p`: `parseRichText` can return block-level nodes, and a `<p>` inside a `<p>`
    23	 * is invalid nesting that the browser silently repairs by splitting the element.
    24	 */
    25	export const ZimmProductModelInfo = ({ modelInfo }: ZimmProductModelInfoProps) => {
    26	  // Guard below the hook, never above it — an early return before `useStyleConfig` makes the
    27	  // hook call conditional, which `react-hooks/rules-of-hooks` reports as an error.
    28	  const styles = useStyleConfig(ZIMM_PRODUCT_MODEL_INFO_RECIPE, {});
    29	  if (isBlankRichText(modelInfo)) return null;
    30	  const content = parseRichText(modelInfo);
    31	
    32	  return (
    33	    <chakra.div __css={styles} textStyle="caption" data-testid="product-model-info">
    34	      {content}
    35	    </chakra.div>
    36	  );
    37	};

