   125	    // 20px hanging above a price that is no longer there.
   126	    await expect(canvas.queryByTestId('product-price')).not.toBeInTheDocument();
   127	    await expect(canvas.getByTestId('product-name')).toBeInTheDocument();
   128	    await expect(canvas.getByTestId('product-description')).toBeInTheDocument();
   129	    await expect(getComputedStyle(root).rowGap).toBe('20px');
   130	  },
   131	};

