import React from 'react';
import { describe, expect, test } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import theme from 'app/theme';
import { ZimmProductName } from '.';
import { ZimmProductModelInfo } from '../zimmProductModelInfo';

const wrap = (ui: React.ReactElement) => render(<ChakraProvider theme={theme}>{ui}</ChakraProvider>);

describe('PROBE: as/testid/recipe reach the DOM', () => {
  test('chakra.p as="h1" renders a real h1, not a p', () => {
    wrap(<ZimmProductName name="Natura Mini Dress" as="h1" />);
    const el = screen.getByRole('heading', { level: 1, name: 'Natura Mini Dress' });
    expect(el.tagName).toBe('H1');
    expect(el).toHaveAttribute('data-testid', 'product-name');
    console.log('[PROBE] Name tagName =', el.tagName, '| testid =', el.getAttribute('data-testid'), '| class =', el.className);
  });

  test('as h2 and h3 too', () => {
    wrap(<><ZimmProductName name="A" as="h2" /><ZimmProductName name="B" as="h3" /></>);
    expect(screen.getByRole('heading', { level: 2, name: 'A' }).tagName).toBe('H2');
    expect(screen.getByRole('heading', { level: 3, name: 'B' }).tagName).toBe('H3');
  });

  test('recipe margin:0 + colour actually land in the emitted CSS', () => {
    wrap(<ZimmProductName name="X" as="h1" />);
    const el = screen.getByTestId('product-name');
    const css = Array.from(document.querySelectorAll('style')).map((s) => s.textContent ?? '').join('\n');
    const own = el.className.split(/\s+/).filter((c) => c.startsWith('css-'));
    console.log('[PROBE] emotion classes =', own.join(','));
    for (const c of own) {
      const rules = css.split('}').filter((r) => r.includes('.' + c));
      console.log('[PROBE] rules for .' + c + ' =>', rules.join(' }\n   ').slice(0, 600));
    }
    console.log('[PROBE] computed marginTop =', getComputedStyle(el).marginTop);
    console.log('[PROBE] computed color =', getComputedStyle(el).color);
  });

  test('model info renders a div with testid', () => {
    wrap(<ZimmProductModelInfo modelInfo="<p>Model is 178cm and wears a size 0</p>" />);
    const el = screen.getByTestId('product-model-info');
    console.log('[PROBE] ModelInfo tagName =', el.tagName, '| innerHTML =', el.innerHTML);
    expect(el.tagName).toBe('DIV');
  });
});
EOF
